import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DIRS, ensureDirs } from "./config.ts";
import { SESSION_ID } from "./diagnostics.ts";
import type { AgentState } from "./agent.ts";

export interface SessionMeta {
  id: string;
  title: string;
  created: string;
  updated: string;
  cwd: string;
  messages: number;
}

function sessionPath(id: string): string {
  return join(DIRS.sessions, `${id}.json`);
}

export function saveSession(state: AgentState, title: string): void {
  if (state.messages.length === 0) return;
  ensureDirs();
  const path = sessionPath(SESSION_ID);
  let created = new Date().toISOString();
  if (existsSync(path)) {
    try {
      created = JSON.parse(readFileSync(path, "utf8")).created ?? created;
    } catch {}
  }
  writeFileSync(
    path,
    JSON.stringify({
      id: SESSION_ID,
      title: title.slice(0, 80),
      created,
      updated: new Date().toISOString(),
      cwd: process.cwd(),
      messages: state.messages,
      totalUsage: state.totalUsage,
    }),
    { mode: 0o600 },
  );
}

export function listSessions(): SessionMeta[] {
  ensureDirs();
  const metas: SessionMeta[] = [];
  try {
    for (const f of readdirSync(DIRS.sessions)) {
      if (!f.endsWith(".json")) continue;
      try {
        const data = JSON.parse(readFileSync(join(DIRS.sessions, f), "utf8"));
        metas.push({
          id: data.id,
          title: data.title ?? "(untitled)",
          created: data.created,
          updated: data.updated,
          cwd: data.cwd ?? "?",
          messages: Array.isArray(data.messages) ? data.messages.length : 0,
        });
      } catch {}
    }
  } catch {}
  return metas.sort((a, b) => (b.updated ?? "").localeCompare(a.updated ?? "")).slice(0, 20);
}

export function loadSession(id: string): { messages: AgentState["messages"]; title: string } | null {
  try {
    const data = JSON.parse(readFileSync(sessionPath(id), "utf8"));
    if (!Array.isArray(data.messages)) return null;
    return { messages: data.messages, title: data.title ?? "(untitled)" };
  } catch {
    return null;
  }
}
